/**
 * Task 6: evaluator. Walks a `ValueGraph` (Task 5) over an `EngDocument`
 * (Task 4) in topological order, producing a fully-typed `EvaluationSnapshot`
 * with one complete, deterministic `CalculationTrace` per calculation/core
 * expression.
 *
 * Algorithm (see task brief for the full narrative):
 *
 * 1. Seed every leaf `ValueBinding` (no `.expression`) straight from its
 *    `.literal`. `input` bindings are validated against their owning node's
 *    `minimum`/`maximum`/`required` props first (Task 4 validated shape
 *    only, not bounds) — a failing input becomes an error-kind `TypedValue`
 *    still occupying its slot, with a `DOMAIN_VIOLATION` diagnostic (chosen
 *    for both bounds and "required" failures, for consistency — see NOTES).
 * 2. Validate decision/choice validity domains against the now-seeded input
 *    values (decisions are graph leaves with no expression edges, so this
 *    must happen out-of-band from the topological walk, not interleaved
 *    with it — see task brief's ordering note).
 * 3. Mark every value in `graph.cyclicValueIds` as errored (the `CALC_CYCLE`
 *    diagnostic already lives on `graph.diagnostics`; this module never
 *    duplicates it). Also mark, as errored, any expression-bearing value
 *    whose owning node already carries a build-time (parse/validation/
 *    resolution) error diagnostic — those must never reach the engine
 *    either.
 * 4. Walk `graph.order`. Each expression-bearing value: check every
 *    dependency is present and non-error in the snapshot (else
 *    `UPSTREAM_ERROR`); otherwise compile + evaluate via the Task 3 adapter,
 *    sharing one `EvaluationBudget` across the whole document pass.
 * 5. Build a `CalculationTrace` for every value that was actually walked
 *    through step 4 (successes and in-walk failures alike), keyed by
 *    `calculationByOutput` when present, else the value's own id (plain
 *    `var` with `expr`).
 */
import { SymbolNode, ConstantNode, bignumber } from 'mathjs';
import type { MathNode } from 'mathjs';
import { sha256Text } from '../runtime.js';

import type { Diagnostic } from '../model/diagnostics.js';
import type { EngDocument, SemanticNode, ValueBinding } from '../model/document.js';
import type { ResolvedExpression } from '../model/expression.js';
import type { TypedValue } from '../model/values.js';
import { canonicalStringify } from '../model/json.js';
import { formatDecimal, formatFloat } from '../model/format.js';
import type { ValueGraph } from './graph.js';
import {
  DEFAULT_ENGINE_POLICY,
  mathjsSafeAdapter,
  type EnginePolicy,
  type EvaluationBudget,
  type NumericProfile,
} from '../engine/mathjs-safe.js';

// ---------------------------------------------------------------------------
// Public types (verbatim from the task brief)
// ---------------------------------------------------------------------------

export interface CalculationTrace {
  calculationId: string;
  targetValueId: string;
  equationNumber?: string;
  purpose?: string;
  symbolicText: string;
  symbolicTex: string;
  substitutedTex: string;
  dependencyIds: string[];
  inputBindings: Array<{
    token: string;
    valueId: string;
    value: TypedValue;
    displayedValue: string;
  }>;
  substitutions: Array<{
    expressionId: string;
    sourceValueId: string;
    displayedValue: string;
  }>;
  unitConversions: Array<{
    valueId: string;
    fromUnit: string;
    toUnit: string;
  }>;
  result: TypedValue;
  displayedResult: string;
  diagnostics: Diagnostic[];
  sourceRefs: string[];
  engineFingerprint: string;
  numericPolicy: Record<string, unknown>;
  traceHash: string;
}

export interface EvaluationSnapshot {
  values: Map<string, TypedValue>;
  traces: Map<string, CalculationTrace>; // calculation or core expression ID
  traceByValueId: Map<string, string>;
  /** Diagnostics generated by THIS evaluation pass only (input bounds,
   * decision domain violations, upstream errors, compile/eval failures).
   * It does NOT include `doc.diagnostics` (Task 4 build-time errors) or
   * `graph.diagnostics` (Task 5's `CALC_CYCLE`/`LIMIT_EXCEEDED`) — callers
   * that need a complete diagnostics picture (e.g. a CLI reporting all
   * errors) must merge all three themselves. */
  diagnostics: Diagnostic[];
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

/** How long, wall-clock, one whole-document evaluation pass is allowed to
 * run before the shared `EvaluationBudget` refuses further `evaluate()`
 * calls. Generous for a reference worksheet; exists only as a backstop. */
const DOCUMENT_EVALUATION_DEADLINE_MS = 30_000;

/** A value supplied at evaluation time instead of the one written in the
 * document. Keyed by value id, or by the id of the node that owns the value
 * when that node owns exactly one — an interactive caller knows its input
 * nodes, not the value ids derived from them.
 *
 * Only a leaf may be overridden. A computed value takes its value from its
 * expression; replacing it would make the document say one thing and evaluate
 * another, so it is refused with a diagnostic rather than honoured. */
export type RuntimeOverrides = ReadonlyMap<string, TypedValue>;

export interface EvaluateOptions {
  overrides?: RuntimeOverrides;
  /** Evaluate only these values and their transitive dependencies. Omit this
   * option for the established whole-document pass. This supports staged
   * workflows where a caller must adopt a tabulated or otherwise
   * non-expression result between two groups of calculations. */
  targetValueIds?: readonly string[];
}

/** Return the dependency closure of explicitly requested values. Unknown
 * targets are diagnosed instead of being ignored: a misspelled stage must
 * never look like a successful evaluation that happened to produce nothing. */
function targetClosure(
  doc: EngDocument,
  graph: ValueGraph,
  targetValueIds: readonly string[],
  snapshot: EvaluationSnapshot,
): Set<string> {
  const active = new Set<string>();
  const pending = [...targetValueIds];
  while (pending.length > 0) {
    const valueId = pending.pop()!;
    if (active.has(valueId)) continue;
    if (!doc.values.has(valueId)) {
      pushDiag(snapshot, 'UNKNOWN_REFERENCE',
        `Evaluation target ${JSON.stringify(valueId)} matches no value in the document.`, undefined,
        { valueId });
      continue;
    }
    active.add(valueId);
    for (const dependencyId of graph.dependencies.get(valueId) ?? []) {
      pending.push(dependencyId);
    }

    // A decision's validity-domain input is an evaluation dependency even
    // though it is deliberately not an arithmetic graph edge. Keep that
    // validation intact when the decision enters a targeted closure.
    const owner = doc.byId.get(doc.values.get(valueId)!.ownerNodeId);
    if (owner?.kind === 'decision') {
      const resolvedChoiceId = typeof owner.props.resolvedChoiceId === 'string'
        ? owner.props.resolvedChoiceId : undefined;
      const selectedOptionId = typeof owner.props.selectedOptionId === 'string'
        ? owner.props.selectedOptionId : undefined;
      const choice = resolvedChoiceId ? doc.byId.get(resolvedChoiceId) : undefined;
      const options = Array.isArray(choice?.props.options) ? choice.props.options : [];
      const selected = options.find((option) => isRecord(option) && option.optionId === selectedOptionId);
      const domain = isRecord(selected) && isRecord(selected.validityDomain)
        ? selected.validityDomain : undefined;
      if (domain && typeof domain.inputId === 'string') pending.push(domain.inputId);
    }
  }
  return active;
}

/** Resolve override keys to value ids, reporting the ones that resolve to
 * nothing, to more than one binding, or to a computed value. Ambiguity is an
 * error rather than a guess: silently picking one of two bindings would be a
 * wrong number presented as a right one. */
function resolveOverrides(
  doc: EngDocument,
  overrides: RuntimeOverrides,
  snapshot: EvaluationSnapshot,
): Map<string, TypedValue> {
  const byOwner = new Map<string, string[]>();
  for (const [valueId, binding] of doc.values) {
    const list = byOwner.get(binding.ownerNodeId);
    if (list) list.push(valueId);
    else byOwner.set(binding.ownerNodeId, [valueId]);
  }

  const resolved = new Map<string, TypedValue>();
  for (const [key, value] of overrides) {
    let valueId: string | undefined;
    if (doc.values.has(key)) {
      valueId = key;
    } else {
      const owned = byOwner.get(key);
      if (owned && owned.length === 1) {
        valueId = owned[0];
      } else if (owned && owned.length > 1) {
        pushDiag(
          snapshot,
          'UNKNOWN_REFERENCE',
          `Override ${JSON.stringify(key)} is ambiguous: node owns values ${owned.join(', ')}.`,
          key,
        );
        continue;
      }
    }
    if (valueId === undefined) {
      pushDiag(snapshot, 'UNKNOWN_REFERENCE',
        `Override ${JSON.stringify(key)} matches no value or node in the document.`, undefined);
      continue;
    }
    const binding = doc.values.get(valueId)!;
    const owner = doc.byId.get(binding.ownerNodeId);
    if (owner?.role === 'decision') {
      pushDiag(snapshot, 'DOMAIN_VIOLATION',
        `Decision ${JSON.stringify(owner.id)} cannot be overridden at evaluation time; author its adopted value and rationale.`,
        owner.id, { valueId });
      continue;
    }
    if (binding.expression) {
      pushDiag(snapshot, 'DOMAIN_VIOLATION',
        `Value ${JSON.stringify(valueId)} is computed and cannot be overridden.`,
        binding.ownerNodeId, { valueId });
      continue;
    }
    resolved.set(valueId, value);
  }
  return resolved;
}

export function evaluateDocument(
  doc: EngDocument,
  graph: ValueGraph,
  options: EvaluateOptions = {},
): EvaluationSnapshot {
  const policy = buildDocumentEnginePolicy(doc.frontmatter);
  const budget: EvaluationBudget = {
    remainingSteps: policy.maxDocumentEvaluationSteps,
    deadlineMs: Date.now() + DOCUMENT_EVALUATION_DEADLINE_MS,
  };
  policy.budget = budget;

  const snapshot: EvaluationSnapshot = {
    values: new Map(),
    traces: new Map(),
    traceByValueId: new Map(),
    diagnostics: [],
  };

  // Owning-node ids that already carry a build-time (parse/validation/
  // resolution) error diagnostic — an expression rooted at one of these must
  // never reach the engine, per the "never evaluate a node with parse,
  // validation, resolution, cycle, or upstream errors" rule.
  const buildErrorNodeIds = new Set(
    doc.diagnostics.filter((d) => d.severity === 'error' && d.nodeId !== undefined).map((d) => d.nodeId!),
  );

  const overrides = options.overrides
    ? resolveOverrides(doc, options.overrides, snapshot)
    : undefined;
  const activeValueIds = options.targetValueIds === undefined
    ? undefined
    : targetClosure(doc, graph, options.targetValueIds, snapshot);

  seedLeaves(doc, snapshot, overrides, activeValueIds);
  validateDecisionDomains(doc, snapshot, policy);
  seedCyclicAndBuildErrorValues(doc, graph, buildErrorNodeIds, snapshot, activeValueIds);
  walkExpressions(doc, graph, buildErrorNodeIds, snapshot, policy, activeValueIds);

  return snapshot;
}

// ---------------------------------------------------------------------------
// Engine policy (mirrors `buildEnginePolicy` in src/parse/build.ts, minus
// diagnostics — front-matter shape was already validated during
// `buildDocument`; an invalid override was already diagnosed there and left
// the field at its `DEFAULT_ENGINE_POLICY` value, which is what we replicate
// here so evaluation uses the exact same policy the build-time `validate()`
// pass checked expressions against).
// ---------------------------------------------------------------------------

function buildDocumentEnginePolicy(frontmatter: Record<string, unknown>): EnginePolicy {
  const policy: EnginePolicy = { ...DEFAULT_ENGINE_POLICY };
  const numericProfile = frontmatter.numericProfile;
  if (numericProfile === 'float64' || numericProfile === 'big-decimal') {
    policy.numericProfile = numericProfile as NumericProfile;
  }
  const displayPrecision = frontmatter.displayPrecision;
  if (typeof displayPrecision === 'number' && Number.isInteger(displayPrecision) && displayPrecision > 0) {
    policy.displaySignificantDigits = displayPrecision;
  }
  return policy;
}

// ---------------------------------------------------------------------------
// Step 1: seed leaves (+ input bounds validation)
// ---------------------------------------------------------------------------

function errorValue(reason: string): TypedValue {
  return { kind: 'error', value: undefined, metadata: { reason } };
}

function pushDiag(
  snapshot: EvaluationSnapshot,
  code: string,
  message: string,
  nodeId: string | undefined,
  details?: Record<string, unknown>,
): Diagnostic {
  const d: Diagnostic = {
    code,
    severity: 'error',
    ...(nodeId !== undefined ? { nodeId } : {}),
    message,
    ...(details !== undefined ? { details } : {}),
  };
  snapshot.diagnostics.push(d);
  return d;
}

function numericMagnitude(value: TypedValue): number | undefined {
  if (value.kind === 'float64' && typeof value.value === 'number') return value.value;
  if (value.kind === 'quantity' && typeof value.value === 'number') return value.value;
  if (value.kind === 'decimal' && typeof value.value === 'string') {
    const n = Number(value.value);
    return Number.isFinite(n) ? n : undefined;
  }
  return undefined;
}

function seedLeaves(
  doc: EngDocument,
  snapshot: EvaluationSnapshot,
  overrides?: ReadonlyMap<string, TypedValue>,
  activeValueIds?: ReadonlySet<string>,
): void {
  for (const [valueId, binding] of doc.values) {
    if (activeValueIds && !activeValueIds.has(valueId)) continue;
    if (binding.expression) continue; // handled by the topological walk
    // A runtime value stands in for the document's literal, and is checked
    // against the same bounds: an out-of-range value typed into an interface
    // must fail the way an out-of-range value written in the source does.
    const override = overrides?.get(valueId);
    if (override) {
      const ownerNode = doc.byId.get(binding.ownerNodeId);
      if (ownerNode?.kind === 'input') {
        const violation = validateInputBounds(ownerNode, override);
        if (violation) {
          pushDiag(snapshot, 'DOMAIN_VIOLATION', violation, binding.ownerNodeId, { valueId });
          snapshot.values.set(valueId, errorValue('DOMAIN_VIOLATION'));
          continue;
        }
      }
      snapshot.values.set(valueId, override);
      continue;
    }
    if (!binding.literal) {
      // Shouldn't happen for a well-formed EngDocument (every non-expression
      // binding is built with a literal), but keep the snapshot total.
      snapshot.values.set(valueId, errorValue('MISSING_LITERAL'));
      continue;
    }

    const ownerNode = doc.byId.get(binding.ownerNodeId);
    if (ownerNode?.kind === 'input') {
      const violation = validateInputBounds(ownerNode, binding.literal);
      if (violation) {
        pushDiag(snapshot, 'DOMAIN_VIOLATION', violation, binding.ownerNodeId, { valueId });
        snapshot.values.set(valueId, errorValue('DOMAIN_VIOLATION'));
        continue;
      }
    }

    snapshot.values.set(valueId, binding.literal);
  }
}

/** Validate an `input` node's `minimum`/`maximum`/`required` props against
 * its seeded literal. `DOMAIN_VIOLATION` is used for every failure mode
 * (missing-but-required, below minimum, above maximum) — the plan's
 * diagnostic-code list has no dedicated "bounds violation" code, and
 * `DOMAIN_VIOLATION` reads more precisely than `TYPE_MISMATCH` for a
 * numerically-out-of-range (but correctly-typed) input. */
function validateInputBounds(node: SemanticNode, literal: TypedValue): string | undefined {
  const props = node.props;
  const required = props.required === true;
  if (required && (literal.value === undefined || literal.value === null)) {
    return `Input ${JSON.stringify(node.id)} is required but has no value.`;
  }
  const minimum = props.minimum;
  const maximum = props.maximum;
  if (typeof minimum !== 'number' && typeof maximum !== 'number') return undefined;

  const magnitude = numericMagnitude(literal);
  if (magnitude === undefined) return undefined; // non-numeric input type; bounds don't apply

  if (typeof minimum === 'number' && magnitude < minimum) {
    return `Input ${JSON.stringify(node.id)} value ${magnitude} is below its minimum ${minimum}.`;
  }
  if (typeof maximum === 'number' && magnitude > maximum) {
    return `Input ${JSON.stringify(node.id)} value ${magnitude} is above its maximum ${maximum}.`;
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// Step 2: decision validity-domain validation
// ---------------------------------------------------------------------------

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Re-uses the real engine adapter to convert a seeded input quantity into a
 * validity domain's unit — never a text relabel. Implemented as a trivial
 * identity expression (`x`) evaluated once with `expectedUnit` set, so the
 * conversion goes through the exact same `.to()` machinery `mathjs-safe.ts`
 * uses for calculation outputs. */
function convertQuantityViaEngine(
  value: TypedValue,
  targetUnit: string,
  policy: EnginePolicy,
): { ok: true; magnitude: number } | { ok: false; diagnostics: Diagnostic[] } {
  const parsed = mathjsSafeAdapter.parse('x');
  if (!parsed.tree) return { ok: false, diagnostics: parsed.diagnostics };
  const compiled = mathjsSafeAdapter.compile(parsed.tree, policy);
  if (!compiled.ok) return { ok: false, diagnostics: compiled.diagnostics };
  const result = mathjsSafeAdapter.evaluate(compiled.value, new Map([['x', value]]), policy, targetUnit);
  if (!result.ok) return { ok: false, diagnostics: result.diagnostics };
  const magnitude = numericMagnitude(result.value);
  if (magnitude === undefined) {
    return {
      ok: false,
      diagnostics: [{ code: 'TYPE_MISMATCH', severity: 'error', message: 'Converted domain value is not numeric.' }],
    };
  }
  return { ok: true, magnitude };
}

function validateDecisionDomains(doc: EngDocument, snapshot: EvaluationSnapshot, policy: EnginePolicy): void {
  for (const node of doc.nodes) {
    if (node.kind !== 'decision' || node.opaque) continue;
    // In a targeted pass an absent decision is outside the requested
    // dependency closure. Do not diagnose its out-of-band validity domain.
    if (!snapshot.values.has(node.id)) continue;
    const props = node.props;
    const resolvedChoiceId = typeof props.resolvedChoiceId === 'string' ? props.resolvedChoiceId : undefined;
    const selectedOptionId = typeof props.selectedOptionId === 'string' ? props.selectedOptionId : undefined;
    if (!resolvedChoiceId || !selectedOptionId) continue;

    const choiceNode = doc.byId.get(resolvedChoiceId);
    const options = Array.isArray(choiceNode?.props.options) ? (choiceNode!.props.options as unknown[]) : [];
    const selected = options.find((o) => isRecord(o) && o.optionId === selectedOptionId);
    if (!selected || !isRecord(selected)) continue;

    const domain = selected.validityDomain;
    if (!isRecord(domain)) continue;
    const inputId = typeof domain.inputId === 'string' ? domain.inputId : undefined;
    const minimum = domain.minimum;
    const maximum = domain.maximum;
    const unit = typeof domain.unit === 'string' ? domain.unit : undefined;
    if (!inputId || typeof minimum !== 'number' || typeof maximum !== 'number' || !unit) continue;

    const inputValue = snapshot.values.get(inputId);
    if (!inputValue || inputValue.kind === 'error') continue; // already diagnosed at its own seat

    const converted = convertQuantityViaEngine(inputValue, unit, policy);
    if (!converted.ok) {
      for (const d of converted.diagnostics) {
        pushDiag(snapshot, d.code, d.message, node.id, { inputId, unit, ...d.details });
      }
      continue;
    }
    if (converted.magnitude < minimum || converted.magnitude > maximum) {
      pushDiag(
        snapshot,
        'DOMAIN_VIOLATION',
        `Decision ${JSON.stringify(node.id)}: controlling input ${JSON.stringify(inputId)} (${converted.magnitude} ${unit}) is outside option ${JSON.stringify(selectedOptionId)}'s validity domain [${minimum}, ${maximum}] ${unit}.`,
        node.id,
        { inputId, value: converted.magnitude, unit, minimum, maximum, optionId: selectedOptionId },
      );
    }
  }
}

// ---------------------------------------------------------------------------
// Step 3: cyclic + build-time-invalid values
// ---------------------------------------------------------------------------

function seedCyclicAndBuildErrorValues(
  doc: EngDocument,
  graph: ValueGraph,
  buildErrorNodeIds: Set<string>,
  snapshot: EvaluationSnapshot,
  activeValueIds?: ReadonlySet<string>,
): void {
  for (const id of graph.cyclicValueIds) {
    if (activeValueIds && !activeValueIds.has(id)) continue;
    snapshot.values.set(id, errorValue('CALC_CYCLE'));
  }
  for (const [valueId, binding] of doc.values) {
    if (activeValueIds && !activeValueIds.has(valueId)) continue;
    if (!binding.expression) continue;
    if (graph.cyclicValueIds.has(valueId)) continue; // already handled above
    if (buildErrorNodeIds.has(binding.ownerNodeId)) {
      snapshot.values.set(valueId, errorValue('BUILD_TIME_ERROR'));
    }
  }
}

// ---------------------------------------------------------------------------
// Step 4/5: topological walk + trace construction
// ---------------------------------------------------------------------------

function walkExpressions(
  doc: EngDocument,
  graph: ValueGraph,
  buildErrorNodeIds: Set<string>,
  snapshot: EvaluationSnapshot,
  policy: EnginePolicy,
  activeValueIds?: ReadonlySet<string>,
): void {
  for (const valueId of graph.order) {
    if (activeValueIds && !activeValueIds.has(valueId)) continue;
    const binding = doc.values.get(valueId);
    if (!binding?.expression) continue; // leaf, already seeded in step 1
    if (snapshot.values.has(valueId)) continue; // already seeded as errored (step 3)

    const expr = binding.expression;
    const deps = graph.dependencies.get(valueId) ?? expr.symbolRefs.map((r) => r.targetValueId);

    const missingOrErrored = deps.find((depId) => {
      const v = snapshot.values.get(depId);
      return v === undefined || v.kind === 'error';
    });
    if (missingOrErrored !== undefined) {
      const diag = pushDiag(
        snapshot,
        'UPSTREAM_ERROR',
        `Value ${JSON.stringify(valueId)} depends on ${JSON.stringify(missingOrErrored)}, which failed to evaluate.`,
        binding.ownerNodeId,
        { dependency: missingOrErrored },
      );
      snapshot.values.set(valueId, errorValue('UPSTREAM_ERROR'));
      recordTrace(doc, snapshot, valueId, binding, expr, deps, errorValue('UPSTREAM_ERROR'), [diag], policy, []);
      continue;
    }

    const compiled = mathjsSafeAdapter.compile(expr.tree, policy);
    if (!compiled.ok) {
      const diags = compiled.diagnostics.map((d) => pushDiag(snapshot, d.code, d.message, binding.ownerNodeId, d.details));
      const err = errorValue('EVAL_ERROR');
      snapshot.values.set(valueId, err);
      recordTrace(doc, snapshot, valueId, binding, expr, deps, err, diags, policy, []);
      continue;
    }

    const scope = new Map<string, TypedValue>();
    for (const ref of expr.symbolRefs) {
      scope.set(ref.token, snapshot.values.get(ref.targetValueId)!);
    }

    const expectedUnit = binding.canonicalUnit;
    const unitConversions: CalculationTrace['unitConversions'] = [];
    let rawUnitLabel: string | undefined;
    if (expectedUnit !== undefined) {
      const rawResult = mathjsSafeAdapter.evaluate(compiled.value, scope, policy);
      if (rawResult.ok && rawResult.value.kind === 'quantity') {
        rawUnitLabel = rawResult.value.canonicalUnit;
      }
    }

    const result = mathjsSafeAdapter.evaluate(compiled.value, scope, policy, expectedUnit);
    if (!result.ok) {
      const diags = result.diagnostics.map((d) => pushDiag(snapshot, d.code, d.message, binding.ownerNodeId, d.details));
      const err = errorValue('EVAL_ERROR');
      snapshot.values.set(valueId, err);
      recordTrace(doc, snapshot, valueId, binding, expr, deps, err, diags, policy, []);
      continue;
    }

    if (expectedUnit !== undefined && rawUnitLabel !== undefined && rawUnitLabel !== expectedUnit) {
      unitConversions.push({ valueId, fromUnit: rawUnitLabel, toUnit: expectedUnit });
    }

    snapshot.values.set(valueId, result.value);
    recordTrace(doc, snapshot, valueId, binding, expr, deps, result.value, [], policy, unitConversions);
  }
}

// ---------------------------------------------------------------------------
// Trace construction
// ---------------------------------------------------------------------------

function displayValue(value: TypedValue, policy: EnginePolicy): string {
  switch (value.kind) {
    case 'float64':
      return typeof value.value === 'number' ? formatFloat(value.value, policy.displaySignificantDigits) : String(value.value);
    case 'decimal':
      return typeof value.value === 'string' ? formatDecimal(value.value, policy.displaySignificantDigits) : String(value.value);
    case 'quantity': {
      const magnitude = typeof value.value === 'number'
        ? formatFloat(value.value, policy.displaySignificantDigits)
        : typeof value.value === 'string'
          ? formatDecimal(value.value, policy.displaySignificantDigits)
          : String(value.value);
      const unit = value.canonicalUnit ?? '';
      return unit ? `${magnitude} ${unit}` : magnitude;
    }
    case 'boolean':
      return String(value.value);
    case 'string':
      return String(value.value);
    case 'error':
      return '<error>';
    case 'undefined':
    default:
      return '<undefined>';
  }
}

/** Substitutes each `SymbolNode` in `tree` matching a resolved token with a
 * fresh `SymbolNode` carrying that value's CURRENT display symbol (not the
 * original source token), so a rename after parsing is reflected in
 * rendering without touching resolved identity (`targetValueId`s). */
function renderSymbolic(tree: unknown, expr: ResolvedExpression, doc: EngDocument): { text: string; tex: string } {
  const currentSymbolByToken = new Map<string, string>();
  for (const ref of expr.symbolRefs) {
    const targetBinding = doc.values.get(ref.targetValueId);
    if (targetBinding) currentSymbolByToken.set(ref.token, targetBinding.symbol);
  }
  const substituted = (tree as MathNode).transform((node: MathNode): MathNode => {
    if (node.type === 'SymbolNode') {
      const name = (node as unknown as { name: string }).name;
      const currentSymbol = currentSymbolByToken.get(name);
      if (currentSymbol !== undefined) {
        return new SymbolNode(currentSymbol) as unknown as MathNode;
      }
    }
    return node;
  });
  return { text: mathjsSafeAdapter.toText(substituted), tex: mathjsSafeAdapter.toTex(substituted) };
}

/** Builds the AST node that stands in for a symbol during substitution.
 * Uses the value's own numeric magnitude (rounded to the policy's display
 * precision), not the string already computed for `displayedValue` —
 * `displayedValue` may carry a unit suffix or (for `decimal`) exponential
 * notation that is not a bare numeric literal, and mathjs renders a
 * `ConstantNode` holding a string as `\mathtt{"..."}` rather than a number,
 * which is not valid substituted TeX. Units are dropped: the symbolic AST
 * never carried them either. */
function substitutedNodeFor(value: TypedValue, policy: EnginePolicy): MathNode {
  switch (value.kind) {
    case 'float64':
      if (typeof value.value === 'number') {
        return new ConstantNode(Number(formatFloat(value.value, policy.displaySignificantDigits))) as unknown as MathNode;
      }
      break;
    case 'decimal':
      if (typeof value.value === 'string') {
        return new ConstantNode(bignumber(formatDecimal(value.value, policy.displaySignificantDigits))) as unknown as MathNode;
      }
      break;
    case 'quantity':
      if (typeof value.value === 'number') {
        return new ConstantNode(Number(formatFloat(value.value, policy.displaySignificantDigits))) as unknown as MathNode;
      }
      if (typeof value.value === 'string') {
        return new ConstantNode(bignumber(formatDecimal(value.value, policy.displaySignificantDigits))) as unknown as MathNode;
      }
      break;
    case 'boolean':
      return new ConstantNode(Boolean(value.value)) as unknown as MathNode;
    default:
      break;
  }
  // string / error / undefined / unrecognized shapes: no numeric literal
  // exists, so fall back to a symbol carrying the display text.
  return new SymbolNode(displayValue(value, policy)) as unknown as MathNode;
}

/** Substitutes each `SymbolNode` matching a resolved token with the value
 * node from `substitutedNodeFor`, then runs it through the SAME TeX emitter
 * `renderSymbolic` uses — never string replacement on `symbolic.tex` — so
 * structure (e.g. a `\frac`) survives substitution intact. */
function renderSubstituted(
  tree: unknown,
  expr: ResolvedExpression,
  snapshot: EvaluationSnapshot,
  policy: EnginePolicy,
): string {
  const valueByToken = new Map<string, TypedValue>();
  for (const ref of expr.symbolRefs) {
    valueByToken.set(ref.token, snapshot.values.get(ref.targetValueId) ?? errorValue('UNKNOWN'));
  }
  const substituted = (tree as MathNode).transform((node: MathNode): MathNode => {
    if (node.type === 'SymbolNode') {
      const name = (node as unknown as { name: string }).name;
      const value = valueByToken.get(name);
      if (value !== undefined) {
        return substitutedNodeFor(value, policy);
      }
    }
    return node;
  });
  return mathjsSafeAdapter.toTex(substituted);
}

function traceKeyFor(doc: EngDocument, valueId: string): string {
  return doc.calculationByOutput.get(valueId) ?? valueId;
}

function recordTrace(
  doc: EngDocument,
  snapshot: EvaluationSnapshot,
  valueId: string,
  binding: ValueBinding,
  expr: ResolvedExpression,
  dependencyIds: string[],
  result: TypedValue,
  diagnostics: Diagnostic[],
  policy: EnginePolicy,
  unitConversions: CalculationTrace['unitConversions'],
): void {
  const calculationId = traceKeyFor(doc, valueId);
  const calcNode = doc.calculationByOutput.has(valueId) ? doc.byId.get(binding.ownerNodeId) : undefined;

  const equationNumber =
    calcNode?.props.equationNumber !== undefined ? String(calcNode.props.equationNumber) : undefined;
  const purpose = typeof calcNode?.props.purpose === 'string' ? (calcNode.props.purpose as string) : undefined;
  const sourceRefs = calcNode
    ? asStringArray(calcNode.props.resolvedSourceRefs) ?? []
    : [];

  const symbolic = renderSymbolic(expr.tree, expr, doc);
  const substitutedTex = renderSubstituted(expr.tree, expr, snapshot, policy);

  const inputBindings: CalculationTrace['inputBindings'] = [];
  const substitutions: CalculationTrace['substitutions'] = [];
  for (const ref of expr.symbolRefs) {
    const depValue = snapshot.values.get(ref.targetValueId) ?? errorValue('UNKNOWN');
    const displayed = displayValue(depValue, policy);
    inputBindings.push({ token: ref.token, valueId: ref.targetValueId, value: depValue, displayedValue: displayed });
    substitutions.push({ expressionId: ref.expressionNodeId, sourceValueId: ref.targetValueId, displayedValue: displayed });
  }

  const displayedResult = displayValue(result, policy);
  const engineFingerprint = mathjsSafeAdapter.fingerprint(policy);
  const numericPolicy: Record<string, unknown> = {
    numericProfile: policy.numericProfile,
    precision: policy.precision,
    roundingMode: policy.roundingMode,
    displaySignificantDigits: policy.displaySignificantDigits,
  };

  const traceWithoutHash: Omit<CalculationTrace, 'traceHash'> = {
    calculationId,
    targetValueId: valueId,
    ...(equationNumber !== undefined ? { equationNumber } : {}),
    ...(purpose !== undefined ? { purpose } : {}),
    symbolicText: symbolic.text,
    symbolicTex: symbolic.tex,
    substitutedTex,
    dependencyIds,
    inputBindings,
    substitutions,
    unitConversions,
    result,
    displayedResult,
    diagnostics,
    sourceRefs,
    engineFingerprint,
    numericPolicy,
  };

  const traceHash = sha256Text(canonicalStringify(traceWithoutHash));
  const trace: CalculationTrace = { ...traceWithoutHash, traceHash };

  snapshot.traces.set(calculationId, trace);
  snapshot.traceByValueId.set(valueId, calculationId);
}

function asStringArray(value: unknown): string[] | undefined {
  if (typeof value === 'string') return [value];
  if (Array.isArray(value) && value.every((v) => typeof v === 'string')) return value as string[];
  return undefined;
}
